'use strict';
// SAM v2 strict-profile spec of src/host.impl.ts: three nodes, one election (term 1),
// and the network as a set of in-flight messages. Each message is sent at most once
// (a node times out at most once, and answers each RequestVote once), so a sorted
// array of message tags is an exact model of the network.
//   RV:<cand>><to>          RequestVote { from: cand, term: 1 }
//   VR:<voter>><cand>:<T|F> VoteReply   { term: 1, granted }

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const NODES = ['n0', 'n1', 'n2'];
const MAJORITY = 2;

const INITIAL_STATE = {
  n0Role: 'follower', n0Term: 0, n0VotedFor: null, n0Votes: [],
  n1Role: 'follower', n1Term: 0, n1VotedFor: null, n1Votes: [],
  n2Role: 'follower', n2Term: 0, n2VotedFor: null, n2Votes: [],
  net: [],
};

const MESSAGES = [];
for (const a of NODES) for (const b of NODES) if (a !== b) {
  MESSAGES.push(`RV:${a}>${b}`, `VR:${a}>${b}:T`, `VR:${a}>${b}:F`);
}

const nodeKeys = (n) => [`${n}Role`, `${n}Term`, `${n}VotedFor`, `${n}Votes`];
const allKeys = Object.keys(INITIAL_STATE);
const others = (touched) => allKeys.filter((k) => !touched.includes(k));
const withMsgs = (net, remove, add) =>
  [...net.filter((m) => m !== remove), ...add].sort();

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape: {
      n0Role: { type: 'string' }, n0Term: { type: 'number' }, n0VotedFor: { type: ['string', 'null'] }, n0Votes: { type: 'array' },
      n1Role: { type: 'string' }, n1Term: { type: 'number' }, n1VotedFor: { type: ['string', 'null'] }, n1Votes: { type: 'array' },
      n2Role: { type: 'string' }, n2Term: { type: 'number' }, n2VotedFor: { type: ['string', 'null'] }, n2Votes: { type: 'array' },
      net: { type: 'array' },
    },
    actions: {
      TIMEOUT: {
        action: (data = {}) => ({ ...data }),
        schema: { node: { type: 'string' } },
        domain: [{ node: 'n0' }, { node: 'n1' }, { node: 'n2' }, { node: 'n9' }],
      },
      DELIVER: {
        action: (data = {}) => ({ ...data }),
        schema: { msg: { type: 'string' } },
        domain: MESSAGES.map((msg) => ({ msg })),
      },
    },
    acceptors: {
      TIMEOUT: (model) => (proposal, { reject, next, unchanged }) => {
        const n = proposal.node;
        if (!NODES.includes(n)) return reject('unknown-node');
        if (model[`${n}Role`] !== 'follower' || model[`${n}Term`] !== 0) return reject('cannot-start-election');
        next[`${n}Role`] = 'candidate';
        next[`${n}Term`] = 1;
        next[`${n}VotedFor`] = n;
        next[`${n}Votes`] = [n];
        next.net = withMsgs(model.net, null, NODES.filter((o) => o !== n).map((o) => `RV:${n}>${o}`));
        unchanged(...others([...nodeKeys(n), 'net']));
      },
      DELIVER: (model) => (proposal, { reject, next, unchanged }) => {
        const msg = proposal.msg;
        if (!model.net.includes(msg)) return reject('not-in-flight');
        const m = /^(RV|VR):(n\d)>(n\d)(?::([TF]))?$/.exec(msg);
        const [, kind, from, to, g] = m;
        if (kind === 'RV') {
          // `to` receives RequestVote from candidate `from`
          let granted;
