const instance = createInstance({ strict: true, hasAsyncActions: false });

const NODES = ['n0', 'n1', 'n2'];
const MAJORITY = 2;

const INITIAL_STATE = {
  n0Role: 'follower', n0Term: 0, n0VotedFor: null, n0Votes: [],
  n1Role: 'follower', n1Term: 0, n1VotedFor: null, n1Votes: [],
  n2Role: 'follower', n2Term: 0, n2VotedFor: null, n2Votes: [],
  net: [],
};

const MESSAGES = [];
for (const a of NODES) for (const b of NODES) if (a !== b) {
  MESSAGES.push(`RV:${a}>${b}`, `VR:${a}>${b}:T`, `VR:${a}>${b}:F`);
}

const nodeKeys = (n) => [`${n}Role`, `${n}Term`, `${n}VotedFor`, `${n}Votes`];
const allKeys = Object.keys(INITIAL_STATE);
const others = (touched) => allKeys.filter((k) => !touched.includes(k));
const withMsgs = (net, remove, add) =>
  [...net.filter((m) => m !== remove), ...add].sort();

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape: {
      n0Role: { type: 'string' }, n0Term: { type: 'number' }, n0VotedFor: { type: 'string', nullable: true }, n0Votes: { type: 'array' },
      n1Role: { type: 'string' }, n1Term: { type: 'number' }, n1VotedFor: { type: 'string', nullable: true }, n1Votes: { type: 'array' },
      n2Role: { type: 'string' }, n2Term: { type: 'number' }, n2VotedFor: { type: 'string', nullable: true }, n2Votes: { type: 'array' },
      net: { type: 'array' },
    },
    actions: {
      TIMEOUT: {
        action: (data = {}) => ({ ...data }),
        schema: { node: { type: 'string' } },
        domain: [{ node: 'n0' }, { node: 'n1' }, { node: 'n2' }, { node: 'n9' }],
      },
      DELIVER: {
        action: (data = {}) => ({ ...data }),
        schema: { msg: { type: 'string' } },
        domain: MESSAGES.map((msg) => ({ msg })),
      },
    },
    acceptors: {
      TIMEOUT: (model) => (proposal, { reject, next, unchanged }) => {
        const n = proposal.node;
        if (!NODES.includes(n)) return reject('unknown-node');
        if (model[`${n}Role`] !== 'follower' || model[`${n}Term`] !== 0) return reject('cannot-start-election');
        next[`${n}Role`] = 'candidate';
        next[`${n}Term`] = 1;
        next[`${n}VotedFor`] = n;
        next[`${n}Votes`] = [n];
        next.net = withMsgs(model.net, null, NODES.filter((o) => o !== n).map((o) => `RV:${n}>${o}`));
        unchanged(...others([...nodeKeys(n), 'net']));
      },
      DELIVER: (model) => (proposal, { reject, next, unchanged }) => {
        const msg = proposal.msg;
        if (!model.net.includes(msg)) return reject('not-in-flight');
        const m = /^(RV|VR):(n\d)>(n\d)(?::([TF]))?$/.exec(msg);
        const [, kind, from, to, g] = m;
        if (kind === 'RV') {
          // `to` receives RequestVote from candidate `from`
          let granted;
          if (model[`${to}Term`] < 1) {
            next[`${to}Role`] = 'follower';
            next[`${to}Term`] = 1;
            next[`${to}VotedFor`] = from;
            next[`${to}Votes`] = [];
            granted = true;
          } else {
            const voted = model[`${to}VotedFor`];
            granted = (model[`${to}Role`] === 'follower' && voted === null) || voted === from;
            if (granted) next[`${to}VotedFor`] = from;
            else unchanged(`${to}VotedFor`);
            unchanged(`${to}Role`, `${to}Term`, `${to}Votes`);
          }
          next.net = withMsgs(model.net, msg, [`VR:${to}>${from}:${granted ? 'T' : 'F'}`]);
          unchanged(...others([...nodeKeys(to), 'net']));
          return;
        }
        // VoteReply from voter `from` to candidate `to`
        const counts = model[`${to}Role`] === 'candidate' && model[`${to}Term`] === 1 && g === 'T';
        next.net = withMsgs(model.net, msg, []);
        if (counts) {
          const votes = model[`${to}Votes`].includes(from)
            ? model[`${to}Votes`] : [...model[`${to}Votes`], from].sort();
          next[`${to}Votes`] = votes;
          next[`${to}Role`] = votes.length >= MAJORITY ? 'leader' : 'candidate';
          unchanged(...others([`${to}Votes`, `${to}Role`, 'net']));
        } else {
          unchanged(...others(['net']));
        }
      },
    },
    reactors: [],
  },
});

const { intents } = control;

const getState = () => instance({}).getState();
const setState = (snapshot) => { instance({}).setState(snapshot); };
const init = () => { setState(INITIAL_STATE); };

const actions = {
  TIMEOUT: (data = {}) => intents.TIMEOUT(data),
  DELIVER: (data = {}) => intents.DELIVER(data),
};

module.exports = { instance, init, actions, getState, setState };

