// Drives src/host.impl.ts through random scenarios and writes one NDJSON trace per
// scenario to spec/traces/, in the contract's observable state.
// `nXVotes` is not exposed by the host interface; it is reconstructed from what the
// harness delivered: the candidate itself plus every granted VoteReply delivered to
// it while it was a candidate (the votes the brief says a candidate counts).
// Run: node spec/capture.ts
import { mkdirSync, writeFileSync, rmSync } from 'node:fs';
import createHost from '../src/host.impl.ts';
import type { Host, Message } from '../host.ts';

const NODES = ['n0', 'n1', 'n2'];
const dir = new URL('./traces/', import.meta.url);

const tag = (m: Message): string =>
  m.action === 'RequestVote'
    ? `RV:${m.data.from}>${m.to}`
    : `VR:${m.from}>${m.to}:${m.data.granted ? 'T' : 'F'}`;

let seed = 12345;
const rand = (n: number) => {
  seed = (seed * 1103515245 + 12345) & 0x7fffffff;
  return seed % n;
};

async function snapshot(h: Host, votes: Map<string, string[]>) {
  const s: Record<string, unknown> = {};
  for (const n of NODES) {
    const v = (await h.node(n))!;
    s[`${n}Role`] = v.role;
    s[`${n}Term`] = v.term;
    s[`${n}VotedFor`] = v.votedFor;
    s[`${n}Votes`] = [...(votes.get(n) ?? [])].sort();
  }
  s.net = (await h.inFlight()).map(tag).sort();
  return s;
}

async function scenario(i: number, steps: number) {
  const h = await createHost();
  const votes = new Map<string, string[]>();
  const lines: string[] = [];
  for (let k = 0; k < steps; k++) {
    const pre = await snapshot(h, votes);
    const flight = await h.inFlight();
    let action: string, data: Record<string, unknown>;
    const r = rand(10);
    if (flight.length === 0 || r < 2) {
      const node = ['n0', 'n1', 'n2', 'n9'][rand(4)];
      action = 'TIMEOUT'; data = { node };
      const out = await h.timeout(node);
      if (out.ok) votes.set(node, [node]);
    } else if (r < 3) {
      // a glitch: deliver a message that is not in flight
      action = 'DELIVER'; data = { msg: 'VR:n0>n1:T' };
      if (!flight.some((m) => tag(m) === 'VR:n0>n1:T')) await h.deliver('nope');
      else continue;
    } else {
      const m = flight[rand(flight.length)];
      action = 'DELIVER'; data = { msg: tag(m) };
      const before = await h.node(m.to);
      await h.deliver(m.id);
      if (m.action === 'VoteReply' && m.data.granted === true && before!.role === 'candidate') {
        const vs = votes.get(m.to) ?? [];
        if (!vs.includes(m.from)) votes.set(m.to, [...vs, m.from]);
      }
    }
    lines.push(JSON.stringify({ pre, action, data, post: await snapshot(h, votes) }));
  }
  writeFileSync(new URL(`s${String(i).padStart(3, '0')}.ndjson`, dir), lines.join('\n') + '\n');
}

rmSync(dir, { recursive: true, force: true });
mkdirSync(dir, { recursive: true });
for (let i = 0; i < 60; i++) await scenario(i, 12);
console.log('wrote 60 traces');

