'use strict';
// SAM v2 strict-profile spec of src/host.impl.ts: three nodes, one election (term 1),
// the leader's announcement, and the network as a set of in-flight messages. Each
// message is sent at most once (a node times out at most once, answers each
// RequestVote once, and becomes leader at most once), so a sorted array of message
// tags is an exact model of the network.
//   RV:<cand>><to>          RequestVote { from: cand, term: 1 }
//   VR:<voter>><cand>:<T|F> VoteReply   { term: 1, granted }
//   LD:<leader>><to>        Leader      { from: leader, term: 1 }

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const NODES = ['n0', 'n1', 'n2'];
const MAJORITY = 2;

const INITIAL_STATE = {
  n0Role: 'follower', n0Term: 0, n0VotedFor: null, n0Leader: null, n0Votes: [],
  n1Role: 'follower', n1Term: 0, n1VotedFor: null, n1Leader: null, n1Votes: [],
  n2Role: 'follower', n2Term: 0, n2VotedFor: null, n2Leader: null, n2Votes: [],
  net: [],
};

const MESSAGES = [];
for (const a of NODES) for (const b of NODES) if (a !== b) {
  MESSAGES.push(`RV:${a}>${b}`, `VR:${a}>${b}:T`, `VR:${a}>${b}:F`, `LD:${a}>${b}`);
}

const nodeKeys = (n) => [`${n}Role`, `${n}Term`, `${n}VotedFor`, `${n}Leader`, `${n}Votes`];
const allKeys = Object.keys(INITIAL_STATE);
const others = (touched) => allKeys.filter((k) => !touched.includes(k));
const withMsgs = (net, remove, add) =>
  [...net.filter((m) => m !== remove), ...add].sort();

const nodeShape = {
  Role: { type: 'string' }, Term: { type: 'number' },
  VotedFor: { type: 'string', nullable: true }, Leader: { type: 'string', nullable: true },
  Votes: { type: 'array' },
};
const modelShape = { net: { type: 'array' } };
for (const n of NODES) for (const [k, v] of Object.entries(nodeShape)) modelShape[`${n}${k}`] = v;

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape,
    actions: {
      TIMEOUT: {
        action: (data = {}) => ({ ...data }),
        schema: { node: { type: 'string' } },
        domain: [{ node: 'n0' }, { node: 'n1' }, { node: 'n2' }, { node: 'n9' }],
      },
      DELIVER: {
        action: (data = {}) => ({ ...data }),
        schema: { msg: { type: 'string' } },
        domain: MESSAGES.map((msg) => ({ msg })),
      },
    },
    acceptors: {
      TIMEOUT: (model) => (proposal, { reject, next, unchanged }) => {
        const n = proposal.node;
        if (!NODES.includes(n)) return reject('unknown-node');
        if (model[`${n}Role`] !== 'follower' || model[`${n}Term`] !== 0) return reject('timeout-once');
        next[`${n}Role`] = 'candidate';
        next[`${n}Term`] = 1;
        next[`${n}VotedFor`] = n;
        next[`${n}Votes`] = [n];
        next.net = withMsgs(model.net, null, NODES.filter((o) => o !== n).map((o) => `RV:${n}>${o}`));
        unchanged(...others([`${n}Role`, `${n}Term`, `${n}VotedFor`, `${n}Votes`, 'net']));
      },
      DELIVER: (model) => (proposal, { reject, next, unchanged }) => {
        const msg = proposal.msg;
        if (!model.net.includes(msg)) return reject('not-in-flight');
        const m = /^(RV|VR|LD):(n\d)>(n\d)(?::([TF]))?$/.exec(msg);
        const [, kind, from, to, g] = m;
        if (kind === 'RV') {
          // `to` receives RequestVote from candidate `from`
          let granted;
          if (model[`${to}Term`] < 1) {
            next[`${to}Role`] = 'follower';
            next[`${to}Term`] = 1;
            next[`${to}VotedFor`] = from;
            next[`${to}Votes`] = [];
            granted = true;
          } else {
            const voted = model[`${to}VotedFor`];
