import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';
import type { Host } from '../host.ts';

const IDS = ['n0', 'n1', 'n2'];

async function views(h: Host) {
  return Promise.all(IDS.map((id) => h.node(id)));
}

test('fresh system', async () => {
  const h = await createHost();
  for (const v of await views(h)) assert.deepEqual(v, { role: 'follower', term: 0, votedFor: null, leader: null });
  assert.equal(await h.node('n3'), null);
  assert.deepEqual(await h.inFlight(), []);
});

test('timeout makes a candidate and sends RequestVote', async () => {
  const h = await createHost();
  assert.deepEqual(await h.timeout('n0'), { ok: true });
  assert.deepEqual(await h.node('n0'), { role: 'candidate', term: 1, votedFor: 'n0', leader: null });
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 2);
  for (const m of msgs) {
    assert.equal(m.action, 'RequestVote');
    assert.equal(m.from, 'n0');
    assert.deepEqual(m.data, { from: 'n0', term: 1 });
  }
  assert.equal((await h.timeout('n0')).ok, false);
  assert.equal((await h.timeout('zz')).ok, false);
});

test('single candidate wins', async () => {
  const h = await createHost();
  await h.timeout('n1');
  await h.deliverAll();
  assert.deepEqual(await h.node('n1'), { role: 'leader', term: 1, votedFor: 'n1', leader: 'n1' });
  assert.deepEqual(await h.node('n0'), { role: 'follower', term: 1, votedFor: 'n1', leader: 'n1' });
  assert.equal((await h.timeout('n0')).ok, false);
});

test('leader announces itself; a term-0 node joins term 1 without voting', async () => {
  const h = await createHost();
  await h.timeout('n0');
  const toN1 = (await h.inFlight()).find((m) => m.to === 'n1')!;
  await h.deliver(toN1.id);
  const reply = (await h.inFlight()).find((m) => m.action === 'VoteReply')!;
  await h.deliver(reply.id);
  assert.equal((await h.node('n0'))!.role, 'leader');
  const announces = (await h.inFlight()).filter((m) => m.action === 'Leader');
  assert.deepEqual(announces.map((m) => m.to).sort(), ['n1', 'n2']);
  for (const m of announces) assert.deepEqual(m.data, { from: 'n0', term: 1 });
  await h.deliver(announces.find((m) => m.to === 'n2')!.id);
  assert.deepEqual(await h.node('n2'), { role: 'follower', term: 1, votedFor: null, leader: 'n0' });
  assert.equal((await h.timeout('n2')).ok, false);
});

test('a candidate steps down on Leader and keeps its own vote', async () => {
  const h = await createHost();
  await h.timeout('n0');
  await h.timeout('n2');
  const rv = (await h.inFlight()).find((m) => m.from === 'n0' && m.to === 'n1')!;
  await h.deliver(rv.id);
  const reply = (await h.inFlight()).find((m) => m.action === 'VoteReply')!;
  await h.deliver(reply.id);
  const ann = (await h.inFlight()).find((m) => m.action === 'Leader' && m.to === 'n2')!;
  await h.deliver(ann.id);
  assert.deepEqual(await h.node('n2'), { role: 'follower', term: 1, votedFor: 'n2', leader: 'n0' });
  await h.deliverAll();
  assert.deepEqual(await h.node('n0'), { role: 'leader', term: 1, votedFor: 'n0', leader: 'n0' });
  assert.equal((await h.node('n2'))!.role, 'follower');
});

test('voted follower refuses timeout and other candidates', async () => {
  const h = await createHost();
  await h.timeout('n0');
  const rv = (await h.inFlight()).find((m) => m.to === 'n1')!;
  await h.deliver(rv.id);
  assert.equal((await h.timeout('n1')).ok, false);
  await h.timeout('n2');
  const toN1 = (await h.inFlight()).find((m) => m.to === 'n1' && m.action === 'RequestVote')!;
  await h.deliver(toN1.id);
  const reply = (await h.inFlight()).find((m) => m.from === 'n1' && m.to === 'n2')!;
  assert.deepEqual(reply.data, { term: 1, granted: false });
});

// Exhaustive exploration over all timeouts and all delivery orders.
test('safety under every interleaving', async () => {
  let explored = 0;
  async function replay(path: string[]): Promise<Host> {
    const h = await createHost();
    for (const step of path) {
      if (step.startsWith('t:')) await h.timeout(step.slice(2));
      else await h.deliver(step.slice(2));
    }
    return h;
  }
  async function check(h: Host) {
    const vs = (await views(h)) as NonNullable<Awaited<ReturnType<Host['node']>>>[];
    const leaders = vs.filter((v) => v.role === 'leader');
    assert.ok(leaders.length <= 1);
    for (const v of leaders) {
      const id = IDS[vs.indexOf(v)];
      assert.ok(vs.filter((w) => w.votedFor === id).length >= 2);
      assert.equal(v.leader, id);
    }
    // a node only knows a node that really leads
    for (const v of vs) if (v.leader !== null) assert.equal(vs[IDS.indexOf(v.leader)].role, 'leader');
    for (const m of await h.inFlight()) {
      if (m.action === 'Leader') assert.notEqual(vs[IDS.indexOf(m.to)].role, 'leader');
    }
  }
  const seen = new Set<string>();
  async function dfs(path: string[]) {
    const h = await replay(path);
    const key = JSON.stringify([
      await views(h),
      (await h.inFlight()).map((m) => JSON.stringify([m.from, m.to, m.action, m.data])).sort(),
    ]);
    if (seen.has(key)) return;
