'use strict';
// Regenerates the negative controls from spec/election.spec.cjs: each mutant is the
// spec with one planted bug, and check.mjs must report violations on every one.
// Run: node spec/controls/make-mutants.cjs
const fs = require('node:fs');
const path = require('node:path');

const src = fs.readFileSync(path.join(__dirname, '..', 'election.spec.cjs'), 'utf8');

const MUTANTS = [
  {
    file: 'mutant-double-vote.cjs',
    note: 'a term-1 follower grants EVERY RequestVote, even after voting.',
    from: "granted = (model[`${to}Role`] === 'follower' && voted === null) || voted === from;",
    to: "granted = model[`${to}Role`] === 'follower'; // MUTATION: ignores votedFor",
  },
  {
    file: 'mutant-gave-up-counts-votes.cjs',
    note: 'a candidate that gave up still counts late VoteReplies.',
    from: "const counts = model[`${to}Role`] === 'candidate' &&",
    to: "const counts = model[`${to}Role`] !== 'leader' && model[`${to}VotedFor`] === to && // MUTATION",
  },
];

for (const m of MUTANTS) {
  if (!src.includes(m.from)) throw new Error(`anchor not found for ${m.file}`);
  const out = src.replace(m.from, m.to).replace("'use strict';",
    `'use strict';\n// NEGATIVE CONTROL (generated by make-mutants.cjs): ${m.note}\n// The checker must report violations on this module.`);
  fs.writeFileSync(path.join(__dirname, m.file), out);
  console.log('wrote', m.file);
}

