      else if (step.startsWith('c:')) await h.crash(step.slice(2));
      else if (step.startsWith('r:')) await h.recover(step.slice(2));
      else await h.deliver(step.slice(2));
    }
    return h;
  }
  async function check(h: Host) {
    const vs = (await views(h)) as NonNullable<Awaited<ReturnType<Host['node']>>>[];
    const leaders = vs.filter((v) => v.role === 'leader');
    assert.ok(leaders.length <= 1);
    for (const v of leaders) {
      const id = IDS[vs.indexOf(v)];
      assert.ok(vs.filter((w) => w.votedFor === id).length >= 2);
      assert.equal(v.leader, id);
    }
    // a node only knows a node that won a majority (it may have crashed since), and all agree
    const known = new Set(vs.map((v) => v.leader).filter((l) => l !== null));
    assert.ok(known.size <= 1);
    for (const l of known) {
      assert.equal(vs[IDS.indexOf(l!)].votedFor, l);
      assert.ok(vs.filter((w) => w.votedFor === l).length >= 2);
    }
    if (leaders.length === 1) for (const l of known) assert.equal(l, IDS[vs.indexOf(leaders[0])]);
