  n0Role: 'follower', n0Term: 0, n0VotedFor: null, n0Leader: null, n0Votes: [],
  n1Role: 'follower', n1Term: 0, n1VotedFor: null, n1Leader: null, n1Votes: [],
  n2Role: 'follower', n2Term: 0, n2VotedFor: null, n2Leader: null, n2Votes: [],
  net: [],
