// Rules the brief requires, independent of how the spec implements them.
const NODES = ['n0', 'n1', 'n2'];
const MAJORITY = 2;

const leaders = (s) => NODES.filter((n) => s[`${n}Role`] === 'leader');
const supporters = (s, c) => NODES.filter((n) => s[`${n}VotedFor`] === c);

export const stateInvariants = [
  { name: 'at-most-one-leader-in-a-term', pred: (s) => leaders(s).length <= 1 },
  {
    name: 'leader-holds-majority-of-votes',
    pred: (s) => leaders(s).every((l) => supporters(s, l).length >= MAJORITY),
  },
  {
    name: 'candidate-or-leader-voted-for-itself',
    pred: (s) => NODES.every((n) => s[`${n}Role`] === 'follower' || s[`${n}VotedFor`] === n),
  },
  {
    name: 'counted-votes-are-real-votes',
    pred: (s) => NODES.every((n) => s[`${n}Votes`].every((v) => s[`${v}VotedFor`] === n)),
  },
  {
    name: 'term-is-0-or-1-and-term-0-has-no-vote',
    pred: (s) => NODES.every((n) =>
      (s[`${n}Term`] === 0 && s[`${n}VotedFor`] === null && s[`${n}Role`] === 'follower') ||
      s[`${n}Term`] === 1),
  },
  {
    name: 'leader-knows-itself',
    pred: (s) => leaders(s).every((l) => s[`${l}Leader`] === l),
  },
  {
    name: 'known-leader-is-the-leader',
    pred: (s) => NODES.every((n) => s[`${n}Leader`] === null || s[`${s[`${n}Leader`]}Role`] === 'leader'),
  },
  {
    name: 'a-node-that-knows-a-leader-is-in-term-1-and-not-a-candidate',
    pred: (s) => NODES.every((n) => s[`${n}Leader`] === null ||
      (s[`${n}Term`] === 1 && s[`${n}Role`] !== 'candidate')),
  },
  {
    name: 'leader-never-receives-Leader',
    pred: (s) => s.net.every((m) => !m.startsWith('LD:') || s[`${m.slice(6, 8)}Role`] !== 'leader'),
  },
  {
    name: 'no-two-replies-from-one-voter-to-one-candidate',
    pred: (s) => s.net.every((m) => !m.startsWith('VR:') ||
      s.net.filter((o) => o.slice(0, 8) === m.slice(0, 8)).length === 1),
  },
];

export const transitionInvariants = [
  {
    name: 'no-node-votes-twice-in-a-term',
    pred: (pre, _a, _d, post) => NODES.every((n) =>
      pre[`${n}VotedFor`] === null || pre[`${n}Term`] !== post[`${n}Term`] ||
      post[`${n}VotedFor`] === pre[`${n}VotedFor`]),
  },
  {
    name: 'leader-stays-leader',
    pred: (pre, _a, _d, post) => NODES.every((n) =>
      pre[`${n}Role`] !== 'leader' || post[`${n}Role`] === 'leader'),
  },
  {
    name: 'known-leader-never-changes',
    pred: (pre, _a, _d, post) => NODES.every((n) =>
      pre[`${n}Leader`] === null || post[`${n}Leader`] === pre[`${n}Leader`]),
  },
  {
    name: 'candidate-steps-down-keeping-its-own-vote',
    pred: (pre, _a, _d, post) => NODES.every((n) =>
      !(pre[`${n}Role`] === 'candidate' && post[`${n}Role`] === 'follower') ||
      (post[`${n}VotedFor`] === n && post[`${n}Term`] === pre[`${n}Term`])),
  },
  {
    name: 'stepping-down-on-delivery-is-only-on-Leader',
    pred: (pre, a, d, post) => a !== 'DELIVER' || NODES.every((n) =>
      !(pre[`${n}Role`] === 'candidate' && post[`${n}Role`] === 'follower') ||
      (d.msg.startsWith('LD:') && post[`${n}Leader`] !== null)),
  },
  {
    name: 'only-a-candidate-becomes-leader',
    pred: (pre, _a, _d, post) => NODES.every((n) =>
      post[`${n}Role`] !== 'leader' || pre[`${n}Role`] !== 'follower'),
  },
  {
    name: 'giving-up-changes-only-the-role',
    pred: (pre, a, d, post) => a !== 'GIVE_UP' ||
      Object.keys(pre).every((k) => k === `${d.node}Role` ||
        JSON.stringify(pre[k]) === JSON.stringify(post[k])),
  },
];

export default { stateInvariants, transitionInvariants };

