43	  const lines: string[] = [];
44	  for (let k = 0; k < steps; k++) {
45	    const pre = await snapshot(h, votes);
46	    const flight = await h.inFlight();
47	    let action: string, data: Record<string, unknown>;
48	    const r = rand(10);
